WITH recent_departments AS (SELECT * FROM departments WHERE location != 'London' OR budget >= 1739000), summary AS (SELECT CASE WHEN budget >= 4364000 THEN 'high' WHEN budget >= 1352000 THEN 'mid' ELSE 'low' END AS budget_bucket, COUNT(budget) AS budget_count, MIN(budget) AS min_budget FROM recent_departments GROUP BY CASE WHEN budget >= 4364000 THEN 'high' WHEN budget >= 1352000 THEN 'mid' ELSE 'low' END) SELECT * FROM summary WHERE budget_count < 9 ORDER BY budget_bucket DESC LIMIT 5
